INSERT INTO SourceAreas (Name) VALUES
  ('Content & Product Strategy'),
  ('Administration & Operations'),
  ('Strategic Solutions'),
  ('Research, Development & Innovation'),
  ('Academic Affairs');
INSERT INTO Teams (Name, Description) VALUES
  ('Learning Experiences', 'All credit, non-credit, and academic programs, including program governance, faculty engagement, recruitment, and delivery.'),
  ('Learning Ecosystems', 'GT Infinity, instructional design, reusable learning content, and learning analytics that connect and improve learner experiences.'),
  ('Learning Infrastructure', 'The support mechanisms that operate the College, including administration, IT, HR, finance, processes, onboarding, facilities, and organizational systems.'),
  ('Learning Futures', 'Research, development, innovation, experimentation, and the capabilities that position CLL for the future.');
INSERT INTO MajorInitiatives (Code, Title, TeamID, SourceAreaID, StrategyAlign, Initiatives, ProposedTarget, TargetStatus) VALUES
  ('1-01', 'Portfolio & pathways', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Content & Product Strategy'), 'Goals 1 + 3: Credentials & pathways', 'OMS AI; Digital Credentials; Department of Learning Systems (enabling)', 'At least 2 recognized pathways plus badges; AI and Durable Skills; market and financial analysis', 'source'),
  ('1-02', 'Reusable content', (SELECT TeamID FROM Teams WHERE Name='Learning Ecosystems'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Content & Product Strategy'), 'Goal 3: Responsive content', 'Financial & Labor Optimization; GTI2.0', 'More than 1,000 approved objects; at least 20% reuse; non-degree development average of 28 days or less', 'source'),
  ('1-03', 'Data, EdTech & Infinity', (SELECT TeamID FROM Teams WHERE Name='Learning Ecosystems'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Content & Product Strategy'), 'Goals 3 + 4 + 5: Personalization & data', 'GTI2.0; Digital Credentials', 'Infinity 2.0 public launch; 3 data domains connected; personalized journey', 'source'),
  ('1-04', 'Team operating models', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Content & Product Strategy'), 'Goal 5: Adaptive operating model', 'Restructure; Financial & Labor; Consult GT (enabling)', '100% of units; new models documented, approved, and tested', 'source'),
  ('2-01', 'Financial, Operational, and Initiative Dashboards', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Administration & Operations'), 'Goal 5: Data informed, transparent, optimized for impact', 'OMS AI; Digital Credentials; Department of Learning Systems (enabling)', 'One college dashboard and 4 team dashboards live by Q2; monthly review held; data refreshed within 10 business days of period close.', 'needs_review'),
  ('2-02', 'Unified branding and messaging frameworks', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Administration & Operations'), 'Goals 1–5: Initiatives and resources alignment', 'GTI2.0; OMS AI; Department of Learning Systems; Consult GT (enabling)', 'Message architecture approved by Q1; all 4 teams implement by Q3; at least 90% of reviewed public-facing assets align by Q4.', 'needs_review'),
  ('2-03', 'Centralized Process & Procedure workflows', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Administration & Operations'), 'Goal 5: Data informed, transparent, flywheel of improvement', 'Restructure; Financial & Labor; Consult GT (enabling)', 'Document the 10 highest-impact cross-college processes; standardize at least 80% by Q3; reduce median cycle time by 20% by Q4.', 'needs_review'),
  ('2-04', 'Admin & Ops LLM Agent', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Administration & Operations'), 'Goal 5: Adaptive operating model', 'Restructure; Financial & Labor; Consult GT (enabling)', 'Launch a governed MVP by Q2; support 5 priority workflows by Q3; achieve at least 80% user satisfaction in the pilot.', 'needs_review'),
  ('2-05', 'Build Organizational Learning Capability', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Administration & Operations'), 'Goal 5: Innovative culture, aspirational workplace; learning organization', 'Restructure; Consult GT (enabling)', 'All 4 teams run quarterly learning cycles; at least 80% of priority-role staff participate; each team implements 2 capability improvements.', 'needs_review'),
  ('2-06', 'Optimized Org Structure & Resource Onboarding', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Administration & Operations'), 'Goals 1–5: Optimized for learning and a seamless experience', 'Restructure; Financial & Labor; Consult GT (enabling)', 'Approve the target organization by Q1; map 100% of key roles; reach at least 90% role clarity and 60 days or less to productivity for new hires.', 'needs_review'),
  ('3-01', 'Growth Engine Readiness', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Strategic Solutions'), 'Goal 1: Scale and Impact', 'Scalable Growth', 'B2B strategy launched; tech-enabled operating model implemented; repeatable sales and strategic account management processes implemented', 'source'),
  ('3-02', 'Strategic Partnership & Revenue Growth', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Strategic Solutions'), 'Goals 1, 2, 3, 4: Learning systems, research, and impact', 'Scalable Growth; GTI2.0; Department of Learning Systems', '100+ qualified and engaged B2B leads; 5+ new partners secured; 2+ new partners launched; $1M+ ARR', 'source'),
  ('3-03', 'Geographic Expansion', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Strategic Solutions'), 'Goals 2, 3, 4: Global network', 'Scalable Growth; Financial & Labor Optimization', 'Scalable Atria business model established; non-main-campus assets inventoried; 10 locations under exploration; 2 piloted; 2 new sites activated', 'source'),
  ('3-04', 'Asset Utilization', (SELECT TeamID FROM Teams WHERE Name='Learning Infrastructure'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Strategic Solutions'), 'Goal 2: Premier hubs', 'Scalable Growth', 'Increase Peachtree Corners utilization by 25%+; develop or advance the long-term Savannah strategy', 'source'),
  ('4-01', 'RDI Baseline & Dashboard', (SELECT TeamID FROM Teams WHERE Name='Learning Futures'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Research, Development & Innovation'), 'Goal 4: Research Leadership', 'Financial & Labor Optimization', 'Complete the RDI baseline by Q1; capture 100% of active RDI projects; publish a quarterly dashboard beginning in Q2.', 'needs_review'),
  ('4-02', 'Research & Innovation Agenda', (SELECT TeamID FROM Teams WHERE Name='Learning Futures'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Research, Development & Innovation'), 'Goals 1 + 4: Learning & Research Leadership', 'Department of Learning Systems; OMS AI; Restructure', 'Approve 3–5 research and innovation themes by Q1; map 100% of priority investments; activate at least 2 cross-unit collaborations.', 'needs_review'),
  ('4-03', 'Research & Innovation Capacity & Infrastructure', (SELECT TeamID FROM Teams WHERE Name='Learning Futures'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Research, Development & Innovation'), 'Goals 4 + 5: Learning & Research Leadership; revolutionize operating model', 'Restructure; Financial & Labor Optimization', 'Approve a roles, funding, tools, and infrastructure plan by Q2; resolve at least 80% of critical capacity gaps by Q4.', 'needs_review'),
  ('4-04', 'Research & Innovation Mechanism', (SELECT TeamID FROM Teams WHERE Name='Learning Futures'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Research, Development & Innovation'), 'Goals 1 + 3 + 4: Learning & Research Leadership; engage 5M learners', 'OMSAI; GTI2.0; Department of Learning Systems', 'Launch at least 2 innovation mechanisms or calls; initiate 6 pilots; complete stage-gate reviews for 100% and at least 3 scale, adapt, or stop decisions.', 'needs_review'),
  ('4-05', 'CLL Learning & Impact Measures', (SELECT TeamID FROM Teams WHERE Name='Learning Futures'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Research, Development & Innovation'), 'Goals 1–4: Research Leadership', 'GTI2.0; OMS AI; Consult GT; Department of Learning Systems', 'Approve a core learning and impact measure set by Q2; instrument at least 80% of priority offerings; publish quarterly impact results.', 'needs_review'),
  ('4-06', 'Learning Studio/Makerspace Model', (SELECT TeamID FROM Teams WHERE Name='Learning Futures'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Research, Development & Innovation'), 'Goals 1 + 4: Learning & Research Leadership', 'Department of Learning Systems', 'Approve the operating model and business case by Q2; run at least 3 pilots with 150 participants and at least 80% participant satisfaction.', 'needs_review'),
  ('5-01', 'Establish and Implement Faculty Governance Process', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems', 'Approve the faculty governance charter and process by Q1; route 100% of applicable faculty actions through it by Q3.', 'needs_review'),
  ('5-02', 'Develop and Implement a Faculty Evaluation and Promotion System', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems', 'Approve the evaluation and promotion framework by Q2; orient 100% of eligible faculty; complete one pilot cycle and incorporate feedback.', 'needs_review'),
  ('5-03', 'Develop approval/governance process for academic programs and digital credentials', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems; Financial & Labor Optimization', 'Launch one approval process for credit, non-credit, and digital credentials by Q2; route 100% of new offerings through it; reach a median decision time of 45 days or less.', 'needs_review'),
  ('5-04', 'Fill open-rank faculty positions and align faculty work with Strategy 2035', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems', 'Fill 100% of authorized FY2027 faculty searches; align 90-day plans for all new hires to Strategy 2035; establish mentoring plans for all continuing faculty.', 'needs_review'),
  ('5-05', 'Empower faculty to engage in innovative program development and align work functions', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems; Restructure', 'Complete faculty work-function reviews by Q2; engage at least 75% of faculty in program innovation or research; document all redeployment decisions.', 'needs_review'),
  ('5-06', 'Grow the institute-wide faculty network engaged in CLL programs', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems', 'Engage at least 25 faculty collaborators from at least 6 colleges; secure contributions from at least 10 to CLL offerings or initiatives.', 'needs_review'),
  ('5-07', 'Recruit students into traditional academic programs', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goal 1: Catalyze a Learning Society and build a home for transformative learning', 'Department of Learning Systems', 'Approve program-level enrollment targets by Q1; achieve at least 90% of the FY2027 enrollment plan; review yield and retention each term.', 'needs_review'),
  ('5-08', 'Stand up innovative traditional academic programs', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goals 1–5', 'Department of Learning Systems; OMS AI', 'Approve or launch at least 2 programs; move 3 additional concepts through market and academic review; meet at least 90% of approved milestones.', 'needs_review'),
  ('5-09', 'Build coursework as reusable learning experiences', (SELECT TeamID FROM Teams WHERE Name='Learning Experiences'), (SELECT SourceAreaID FROM SourceAreas WHERE Name='Academic Affairs'), 'Goals 1 + 3: Learning; Credentials & pathways', 'OMSAI; GTI2.0; Digital Credentialing; Scalable Growth', 'Build 100% of new coursework as reusable learning modules; achieve at least 20% reuse across offerings; apply metadata and quality standards to every module.', 'needs_review');
